          {layer.type==='image'&&!layer.suiteSource&&<PhotoSourceControls key={layer.id} layer={layer} revision={revision.current} disabled={!loaded||!!recovery||layer.locked||importBusy} getRevision={objectVersion} onError={notice} onReplace={(src,id)=>{if(gesture.current){notice('Finish the current gesture before replacing this photo.');return false;}try{return commit(replacePhotoSource(projectRef.current,id,src));}catch(error){notice(error.message);return false;}}}/>}
